'use strict';
// One shared illustrated icon set: warm timber, parchment and teal enamel.
function gameIcon(name){const shapes={
 ore:'<path d="m4 29 4-15 12-9 13 8 4 17-14 5Z" fill="#718780"/><path d="m9 17 9-8 7 5-5 10Z" fill="#d99b60"/><path d="m24 24 6-7 4 10-8 4Z" fill="#ba7849"/>',
 shells:'<path d="M16 32 4 17Q2 5 13 8q7-12 14 0 12-2 10 10L24 32Z" fill="#edc5a1"/><path d="m20 29-7-18m7 18V9m0 20 8-17m-8 17L7 16m13 13 14-12" fill="none" stroke="#b7856b"/><path d="M15 30h10v5H15Z" fill="#f4dcb3"/>',
 marks:'<path d="m20 3 13 8-2 20-11 6-11-6-2-20Z" fill="#528c7c"/><path d="m20 9 7 19-7-4-7 4Z" fill="#f3d58a"/>',
 wood:'<path d="M7 22 26 12 35 18 16 29Z" fill="#ab723a"/><path d="m9 15 18-8 7 5-18 10Z" fill="#d49d52"/><ellipse cx="12" cy="24" rx="7" ry="6" fill="#efc787"/><ellipse cx="12" cy="24" rx="3" ry="3" fill="none"/><path d="m20 21 12-6m-10 10 11-5"/>',
 berries:'<path d="M19 15q-8-12-13-6 0 9 13 6m2-1q2-12 12-8 0 9-12 8" fill="#83a452"/><path d="m19 8 1 13"/><circle cx="12" cy="23" r="7" fill="#bd637b"/><circle cx="25" cy="22" r="8" fill="#d77d88"/><circle cx="19" cy="29" r="7" fill="#a8526c"/><path d="m10 20 2-1m11-1 3 1m-9 7 2-1" stroke="#f8c2a4"/>',
 crystals:'<path d="m5 31 1-14 6-7 5 7-1 17Z" fill="#ab9ccb"/><path d="m15 33 1-23 7-7 6 9-1 22Z" fill="#c8b8e2"/><path d="m26 33 0-15 5-5 5 7-1 11Z" fill="#9388b8"/><path d="m23 5-1 27m9-16 0 13" stroke="#f4e2f1"/>',
 coins:'<circle cx="20" cy="20" r="15" fill="#bf8b35"/><circle cx="20" cy="18" r="13" fill="#f2cb65"/><circle cx="20" cy="18" r="9" fill="#dda846"/><path d="m20 9 2 6 6 2-6 2-2 7-2-7-6-2 6-2Z" fill="#ffeb9d" stroke="#bf8b35"/>',
 bag:'<path d="M13 12V8q7-6 14 0v4" fill="none"/><path d="m10 11-4 22q13 5 27 0l-4-22Z" fill="#bd8546"/><path d="M9 11q11-7 21 0v11q-11 5-21 0Z" fill="#e0ad62"/><path d="M18 18h6v10h-6Z" fill="#72533a"/><path d="M19 19h4v5h-4Z" fill="#f8d77f"/>',
 home:'<path d="M9 17h23v18H9Z" fill="#cda36a"/><path d="m4 18 16-14 17 14Z" fill="#347a75"/><path d="m9 14 11-9 12 10" fill="none" stroke="#79b0a0"/><path d="M17 24h8v11h-8Z" fill="#74503b"/><path d="M10 20h5v6h-5Zm17 0h5v6h-5Z" fill="#f2d58e"/>',
 friends:'<path d="m9 19-3-14 8 3 4 13m4-2 6-14 6 3-3 15" fill="#88a35c"/><path d="M7 24q0-13 13-13t13 13q0 11-13 11T7 24" fill="#b2c27c"/><ellipse cx="20" cy="29" rx="8" ry="5" fill="#e9dfaa"/><path d="M14 21v3m12-3v3m-7 3h2" stroke="#384c37"/>',
 map:'<path d="m4 8 11-4 12 5 10-4-2 29-10 3-12-5-10 4Z" fill="#ded4a0"/><path d="m15 5-2 26m14-21-2 26" fill="none" stroke="#a99363"/><path d="m8 13 5 5 7-4 9 7 4-8" fill="none" stroke="#6c9f91"/><path d="m12 24 4-3 5 4 6-2" fill="none" stroke="#b69d62"/><path d="m21 12 4-7 4 7-4 5Z" fill="#a7654d"/>',
 tasks:'<path d="M9 7h24v29H9Z" fill="#b4884d"/><path d="m7 8 23-2 3 27-23 3Z" fill="#f2dfac"/><path d="M15 4h10v6H15Z" fill="#b17d40"/><path d="m12 17 2 2 4-5m-5 12 2 2 4-5" fill="none" stroke="#507b60"/><path d="m21 16 6-1m-5 9 6-1" stroke="#a48a56"/>',
 menu:'<path d="M6 7h28v27H6Z" fill="#457f75"/><path d="M12 14h16m-16 6h16m-16 6h16" stroke="#eddda7" stroke-width="3"/>',
 hand:'<path d="M12 23V13q0-4 4-3V6q4-4 5 1v3q4-4 5 1v3q5-2 5 3v11l-7 7H14L5 24q-2-5 3-5Z" fill="#f0d19a"/><path d="M16 11v10m5-12v12m5-8v9" stroke="#b48b57"/>',
 boot:'<path d="m13 5 14 2-4 16 10 6v6H7v-9l4-7Z" fill="#b88850"/><path d="m12 6 16 2-1 5-16-2Z" fill="#e4c586"/><path d="m8 29 24 2v4H7Z" fill="#624c36"/><path d="m13 15 9 2m-10 3 9 2" stroke="#e9cf94"/>',
 tool:'<path d="m10 33 17-24 4 3-17 24Z" fill="#c4995d"/><path d="m13 9 6-5 16 9-4 8-11-7Z" fill="#9eb2a3"/><path d="m14 10 6-3 10 6" fill="none" stroke="#e8e4bb"/>',
 talk:'<path d="M4 7h32v22H21l-10 7v-7H4Z" fill="#efdfab"/><path d="M11 15h18m-18 7h12" stroke="#8d744c"/>',
 fish:'<path d="m5 20 7-9 17 4 7-5-1 18-7-5-16 6Z" fill="#82b8af"/><circle cx="14" cy="18" r="2" fill="#f4e5b6"/><path d="m21 15-4-6 10 6m-7 11 6 6 1-8" fill="#a6d3bd"/>',
 seed:'<path d="M20 35V15M20 23Q2 20 6 8q17 0 14 15m0-6Q22 2 35 5q1 12-15 12" fill="#90ad64"/><path d="m19 34 1-19M10 12l8 8m8-9-5 5" stroke="#50794b"/>',
 check:'<path d="m8 20 8 8L33 9" fill="none" stroke="#dfedaf" stroke-width="5"/>'};return `<svg viewBox="0 0 40 40" aria-hidden="true" focusable="false"><g stroke="#594830" stroke-width="1.6" stroke-linejoin="round" stroke-linecap="round">${shapes[name]||shapes.hand}</g></svg>`;}
const gameHud=document.createElement('div');gameHud.className='game-hud';gameHud.innerHTML=`<header class="resource-rail"><button class="level-medal" data-game="profile" aria-label="Adventure level and progress"><strong id="hero-level">1</strong><span class="level-fill"><i id="hero-xp"></i></span></button><button class="resource-strip" data-game="bag" aria-label="Open inventory"><span>${gameIcon('wood')}<b id="res-wood">0</b></span><span>${gameIcon('berries')}<b id="res-berries">0</b></span><span>${gameIcon('crystals')}<b id="res-crystals">0</b></span><span>${gameIcon('coins')}<b id="res-coins">0</b></span></button></header><button class="task-medallion" data-game="tasks" aria-label="Open adventure tasks">${gameIcon('tasks')}<span>Tasks</span><i id="task-ready" hidden></i></button><nav class="game-dock" aria-label="Game navigation">${[['home','Camp'],['bag','Bag'],['friends','Friends'],['map','Map'],['menu','Menu']].map(([id,label])=>`<button data-game="${id}" aria-label="${label}">${gameIcon(id)}<span>${label}</span>${id==='menu'?'<i id="save-alert" hidden></i>':''}</button>`).join('')}</nav>`;app.append(gameHud);
function shortCount(n){return n>=10000?Math.floor(n/1000)+'k':String(Math.floor(n));}
const compactHud=hud;hud=function(){compactHud();for(const k of ['wood','berries','crystals','coins'])document.getElementById('res-'+k).textContent=shortCount(state[k]);const level=1+Math.floor(state.xp/100);document.getElementById('hero-level').textContent=level;document.getElementById('hero-xp').style.width=(state.xp%100)+'%';const next=MossSystems.chapters.findIndex((_,i)=>!state.life.claimed.includes(i));document.getElementById('task-ready').hidden=next<0||!MossSystems.chapters[next][2](state);const status=SaveStore.status();document.getElementById('save-alert').hidden=!status.problem&&!status.conflict;};
// Action has one contextual verb. Input instructions live in the controls panel.
interactionHUD=function(){const b=document.getElementById('action');let label='Interact',icon='hand';if(activity){label=activity.o.type==='fish'?(activity.elapsed>=activity.duration?'Reel':'Wait'):'Stop';icon=activity.o.type==='fish'?'fish':'tool';}else if(near){const choice={berries:['Pick','berries'],herb:['Pick','seed'],ore:['Mine','tool'],shell:['Collect','fish'],trailboard:['Requests','tasks'],trailgate:['Restore','tool'],landmark:['Restore','home'],log:['Chop','tool'],crystals:['Mine','crystals'],fish:['Fish','fish'],plot:['Garden','seed'],chest:['Collect','bag'],cache:['Search','bag'],workbench:['Craft','tool'],sign:['Read','map'],journal:['Read','tasks'],bridge:['Repair','tool'],seal:['Open','hand'],beacon:['Light','crystals'],bed:['Rest','home']};[label,icon]=choice[near.type]||[near.kind==='human'?'Talk':near.kind==='creature'?'Meet':'Use',near.kind==='human'?'talk':'hand'];if(resourceInfo[near.type]&&(state.cooldowns[near.id]||0)>Date.now()){b.disabled=true;label='Wait';}}if(activity)b.disabled=false;const signature=icon+label;if(b.dataset.art!==signature){b.innerHTML=gameIcon(icon)+`<span>${label}</span>`;b.dataset.art=signature;}b.setAttribute('aria-label',label);b.classList.toggle('has-target',!!near||!!activity);const runButton=document.getElementById('run');if(runButton.dataset.art!=='boot'||!runButton.querySelector('svg')){runButton.innerHTML=gameIcon('boot');runButton.dataset.art='boot';}runButton.setAttribute('aria-label',runLatched?'Switch to walking':'Switch to running');runButton.setAttribute('aria-pressed',String(runLatched));};
function campPanel(){const time=valleyTime();show('Your homestead',`<p class="camp-summary">${map.name} · Day ${time.day} · ${time.rain?'Rain':time.night?'Night':'Daylight'}</p><div class="camp-cards"><button data-ui="bag">${gameIcon('bag')}<b>${bankTotal()}</b><span>Supplies ready</span></button><button data-life="companions">${gameIcon('friends')}<b>${state.team.length} / 4</b><span>Companions</span></button></div><p>Garden south of your home. Craft and upgrade at the workbench inside.</p><div class="actions"><button data-life="journal">Adventure tasks</button><button data-ui="close">Keep exploring</button></div>`,'Camp level '+state.upgrade);}
help=function(){show('Take a breather',`<div class="pause-grid"><button data-extra="audio">${gameIcon('talk')}<span>Music & sound</span></button><button data-life="saves">${gameIcon('bag')}<span>Saves & backup</span></button><button data-game="controls">${gameIcon('hand')}<span>Controls</span></button><button data-artguide="true">${gameIcon('tasks')}<span>Field guide</span></button></div><div class="actions"><button data-extra="fullscreen">Full screen</button><button data-ui="close">Resume</button></div>`,'Mosswild');};
app.addEventListener('click',e=>{const b=e.target.closest('[data-game]');if(!b)return;switch(b.dataset.game){case'bag':bag();break;case'friends':companionMenu();break;case'tasks':adventureMenu();break;case'map':mapPanel();break;case'home':campPanel();break;case'menu':help();break;case'profile':show('Your adventure',`<p>Level ${1+Math.floor(state.xp/100)} · ${state.xp%100} / 100 XP to the next level.</p><p>Gather, grow and finish tasks to earn XP.</p><div class="actions"><button data-life="journal">View tasks</button><button data-ui="close">Continue</button></div>`,'Explorer');break;case'controls':show('Find your own pace','<p><b>Touch:</b> drag the left stick to move. Tap the boot to run. The large button changes to the nearby action.</p><p><b>Keyboard:</b> WASD or arrows move. E or Space interacts. Shift runs.</p><p><b>Controller:</b> left stick moves, A interacts and B runs or closes a menu.</p><div class="actions"><button data-ui="close">Ready</button></div>','Controls');break;}});
// Companions are deliberately smaller than the human, including ears and wings.
creature=function(x,y,name,walk=0){const actual=name==='Pip'?state.life.active:name,step=walk&&Math.sin(walk)<=0?1:0;const sprite=ValleyArt.make('friend-'+actual+'-'+step,a=>ValleyArt.creatureSprite(a,actual,step));const scale=.62;ctx.drawImage(sprite,Math.round(x-48*scale),Math.round(y-80*scale),96*scale,96*scale);};
// Keep context beside the object, not in multiple text banners.
const quietShow=show;show=function(title,body,kicker){quietShow(title,body,kicker);gameHud.classList.add('menu-open');};
const quietClose=close;close=function(){quietClose();gameHud.classList.remove('menu-open');};
hud();

function mapPanel(){const points=[['cottage',70,155,'Mara’s cottage'],['valley',165,185,'Willowmere'],['home',220,115,'Homestead'],['grove',150,45,'Moonleaf Grove'],['meadow',285,200,'Sunlit Meadow'],['riverbank',275,300,'Riverbank'],['cavern',145,320,'Lantern Cavern']];show('The valley',`<div class="world-chart"><svg viewBox="0 0 360 365" role="img" aria-label="World map: Willowmere connects north to Moonleaf Grove, east to Sunlit Meadow, then the Riverbank and Lantern Cavern."><rect x="3" y="3" width="354" height="359" rx="18" fill="#cdd2a1"/><path d="M35 20q45 85 20 140t-30 180m295-315q-35 130 0 230" fill="none" stroke="#86af9b" stroke-width="16"/><path d="m70 155 95 30 55-70m-55 70L150 45m15 140 120 15-10 100-130 20" fill="none" stroke="#f5e2b0" stroke-width="12"/><path d="m70 155 95 30 55-70m-55 70L150 45m15 140 120 15-10 100-130 20" fill="none" stroke="#aa9365" stroke-width="2" stroke-dasharray="4 6"/>${points.map(([id,x,y,name])=>`<g><circle cx="${x}" cy="${y}" r="${id===map.id?17:13}" fill="${id===map.id?'#397c72':'#a17d4e'}" stroke="#f9e8b5" stroke-width="3"/><path d="m${x-6} ${y+2} 6-8 6 8v6h-12Z" fill="#efda9a"/><text x="${x}" y="${y+31}" text-anchor="middle" fill="#3d5138" font-size="10" font-family="sans-serif" font-weight="bold">${name}</text></g>`).join('')}</svg></div><p class="map-caption">You are in ${map.name}.</p><div class="actions"><button data-extra="journal">Trail details</button><button data-ui="close">Back to exploring</button></div>`,'World map');}
